import { Hercai } from "hercai";
import {
  imageReader,
  toDraw,
  aiImagine,
  aiVoice,
  typeWriter,
  groqAnalyzer,
  readFile,
  geminiPro,
  geminiFlash
} from "./utils";
import { 
  ModalBuilder,
  TextInputBuilder,
  TextInputStyle,
  ActionRowBuilder,
  Message,
  PermissionResolvable
} from "discord.js";
import { filters } from "./buttons/tools";
import { imageTools } from "./buttons/drawMenu";
import { whisper } from "./modals-chat/groq/whisper";
import { validateModels} from "./functions/validOptions";
import { chatHercai } from "./modals-chat/hercai/chatModels";
import { otherChatModels } from "./modals-chat/others/otherModels";
import { chatGroq } from "./modals-chat/groq/chatgroq";
import { electronChat } from "./modals-chat/electronHub/chatmodels";

export interface Options {
  /**
   * Configuration options related to voice functionality.
   * @param voice.textVoice Configuration options for text-to-voice functionality.
   * @param voice.textVoice.enable Whether text-to-voice functionality is enabled.
   * @param voice.textVoice.voiceModel The voice model to be used.
   * @param voice.textVoice.voice_code The voice code only for (apexAI and zenithAI model).
   * @param voice.textVoice.apiKey The API key for accessing the voice service only for (apexAI and zenithAI model).
   * @param voice.textVoice.type The type of voice only for (apexAI and zenithAI model).
   */
  voice?: {
      textVoice?: {
          enable?: boolean;
          voiceModel?: string;
          voice_code?: string;
          apiKey?: string;
          type?: string;
      };
  };
  /**
   * Configuration options related to image generation.
   * @param imagine.enable Whether image generation is enabled.
   * @param imagine.drawTrigger The trigger phrases for initiating image generation.
   * @param imagine.imageModal The model for the image generation.
   * @param imagine.numOfImages The number of images to generate.
   * @param imagine.nsfw Configuration options for NSFW filtering.
   * @param imagine.nsfw.enable Whether NSFW filtering is enabled.
   * @param imagine.nsfw.keywords Keywords for NSFW filtering.
   * @param imagine.enhancer Configuration options for image enhancement.
   * @param imagine.enhancer.enable Whether image enhancement is enabled (rewrites your prompt in more descriptive way).
   * @param imagine.enhancer.enhancerModal The model for image enhancement only for (Prodia models).
   * @param imagine.enhancer.cfg_scale The scale for image enhancement only for (Prodia models).
   * @param imagine.enhancer.steps The number of enhancement steps only for (Prodia models).
   * @param imagine.enhancer.seed The seed for image enhancement only for (Prodia models).
   * @param imagine.enhancer.imgStyle The style of the image only for (Prodia models).
   * @param imagine.enhancer.negative_prompt The negative prompt for image enhancement only for (Prodia models).
   * @param imagine.enhancer.sampler The sampler for image enhancement only for (Prodia models).
   */
  imagine?: {
      enable?: boolean;
      drawTrigger?: string[];
      imageModel?: string;
      numOfImages?: number;
      ApiKeys?: {
        groqAPI?: string;
        rsnAPIkey?: string;
        prodiaAPI?: string;
        freesedGPTApi?: string;
        electronHubKey?:  string
      }; 
      nsfw?: {
          enable?: boolean;
          keywords?: string[];
          deepCheck?: boolean;
      };
      enhancer?: {
          enable: boolean;
          enhancerModal?: string | "ESRGAN_4x" | "Lanczos" | "Nearest" | "LDSR" | "R-ESRGAN 4x+" | "R-ESRGAN 4x+ Anime6B" | "ScuNET GAN" | "ScuNET PSNR" | "SwinIR 4x" | undefined;
          cfg_scale?: number;
          steps?: number;
          seed?: number;
          imgStyle?: string | "3d-model" | "analog-film" | "anime" | "cinematic" | "comic-book" | "digital-art" | "enhance" | "isometric" | "fantasy-art" | "isometric" | "line-art" | "low-poly" | "neon-punk" | "origami" | "photographic" | "pixel-art" | "texture" | "craft-clay";
          negative_prompt?: string;
          sampler?: string | "DPM++ 2M Karras" | "DPM++ SDE Karras" | "DPM++ 2M SDE Exponential" | "DPM++ 2M SDE Karras" | "Euler a" | "Euler" | "LMS" | "Heun" | "DPM2" | "DPM2 a" | "DPM++ 2S a" | "DPM++ 2M" | "DPM++ SDE" | "DPM++ 2M SDE" | "DPM++ 2M SDE Heun" | "DPM++ 2M SDE Heun Karras" | "DPM++ 2M SDE Heun Exponential" | "DPM++ 3M SDE" | "DPM++ 3M SDE Karras" | "DPM++ 3M SDE Exponential" | "DPM fast" | "DPM adaptive" | "LMS Karras" | "DPM2 Karras" | "DPM2 a Karras" | "DPM++ 2S a Karras" | "Restart" | "DDIM" | "PLMS" | "UniPC";
          width?: number;
          height?: number;
          upscale?: number;
        };
  };
  /**
   * Configuration options related to chat functionality.
   * @param chat.chatModel The chat model to be used.
   * @param chat.readFiles Whether to read files.
   * @param chat.readImages Whether to read images.
   * @param chat.personality The personality for the chat.
   * @param chat.API_KEY The API key for accessing the chat service.
   * @param chat.lang The Language of the voice message sent.
   * @param chat.memory Configuration options for memory.
   * @param chat.memory.memoryOn Whether memory is enabled.
   * @param chat.memory.id The ID for memory.
   * @param chat.typeWriting Configuration options for typing effect.
   * @param chat.typeWriting.enable Whether the typing effect is enabled.
   * @param chat.typeWriting.speed The speed of typing.
   * @param chat.typeWriting.delay The delay for typing.
   */
  chat?: {
      enable?: boolean;
      returnChat?: Boolean
      chatModel?: string;
      readFiles?: boolean;
      readImages?: boolean;
      personality?: string | any;
      instruction?: string;
      Api_Keys?: {
        groq_API?: string;
        rsn_API?: string;
        prodia_API?: string;
        geminiAPI?: string;
        freesedGPT_Api?: string;
        electronHub_Key?:  string
      }; 
      lang?: string;
      memory?: {
          memoryOn?: boolean;
          id?: string;
      };
      typeWriting?: {
          enable?: boolean;
          speed?: number;
          delay?: number;
      };
  };
  /**
   * Additional configuration options.
   * @param others.messageType Configuration options for message types.
   * @param others.messageType.type The type of message.
   * @param others.messageType.intialContent The initial content of the message.
   * @param others.buttons Buttons configuration.
   * @param others.keywords Keywords for response.
   * @param others.keywordResponses Responses for keywords.
   * @param others.loader Configuration options for loader.
   * @param others.loader.enable Whether the loader is enabled.
   * @param others.loader.loadingMessage The loading message.
   * @param others.loader.loadingTimer The loading timer.
   * @param others.channel Configuration options for channels.
   * @param others.channel.enable Whether channels are enabled.
   * @param others.channel.id The ID of the channels.
   * @param others.permissions Configuration options for permissions.
   * @param others.permissions.enable Whether permissions are enabled.
   * @param others.permissions.role The role for permissions.
   * @param others.permissions.permission The permission.
   * @param others.permissions.blockedUsers Blocked users.
   */
  others?: {
      messageType?: {
          type?: string;
          intialContent?: string;
          sendAs?: string | "embed" | "content";
      };
      onMention?: boolean;
      buttons?: any[];
      keywords?: string[];
      keywordResponses?: Record<string, string>;
      loader?: {
          enable?: boolean;
          loadingMessage?: string;
          loadingTimer?: number;
      };
      channel?: {
          enable?: boolean;
          id?: string[];
      };
      permissions?: {
          enable?: boolean;
          role?: string[];
          permission?: string[];
          blockedUsers?: string[];
      };
  };
}

type Response = string | { content?: string; reply?: string } | any;
const hercai = new Hercai('6eZZOdDwm6Epdzn8mnhcX9SBDkxvoNYcNj9ILS0P44=');


export async function ApexAI (message: Message, aiOptions: Options) {


  const modelsValidate = await validateModels();

  await imageTools(
    message.client,
    ModalBuilder,
    TextInputBuilder,
    TextInputStyle,
    ActionRowBuilder
  );

  await filters(message.client);
  
    let usermsg: string = message.content || ''; 
    let RespondMessage: any;
    const {
      voice: {
          textVoice: {
              enable: textVoiceEnable = false,
              voiceModel: textVoiceModel = "google",
              voice_code: textVoiceCode = "en-US-3",
              apiKey: textVoiceApiKey = "",
              type: textVoiceType = "b"
          } = {}
      } = {},
      imagine: {
        ApiKeys: {
          groqAPI = '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',
          rsnAPIkey = 'rsnai_SbLbFcwdT2h2KoYet2LS0F34', 
          prodiaAPI = 'eaebff6e-c7b2-477c-8edd-9aa91becf1e3',
          freesedGPTApi = null,
          electronHubKey = null
        } = {},
        enable: imagineEnable = false,
        drawTrigger = ["create", "رسم"],
        imageModel = "prodia",
        numOfImages = 2,
        nsfw: {
          enable: nsfwEnabled = false,
          keywords: nsfwKeyWords = [],
          deepCheck: deepCheck = false
      } = {}, 
        enhancer: {
          enable: enhancerOn = false,
          enhancerModal: enhanceModal = 'ESRGAN_4x',
          negative_prompt:  negative_prompt = '',
          cfg_scale: cfgScale = 7,
          sampler: sampler = 'DDIM',
          steps: steps = 20,
          seed: seed = -1,
          imgStyle: imgStyle = 'enhance',
          width: width = 512,
          height: height = 512,
          upscale: upscale = 2
        } = {},
    } = {},
      chat: {
          enable: chatEnable = true,
          chatModel = "v3",
          readFiles = false,
          readImages = false,
          returnChat = true,
          instruction = '',
          Api_Keys: {
            groq_API = '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',
            rsn_API = 'rsnai_SbLbFcwdT2h2KoYet2LS0F34', 
            geminiAPI = null,
            freesedGPT_Api = null,
            electronHub_Key = null
          } = {},
          personality = null,
          lang = 'en',
          memory: {
            memoryOn: memoryOn = false,
            id: memoryId = ''
            } = {},
          typeWriting: {
              enable: typeWritingEnable = false,
              speed = 70,
              delay = 2000
          } = {}
      } = {},
      others: {
          onMention = false,
          messageType: {
            type: msgType = 'reply',
            intialContent: msgContent = ''
          } = {},
          buttons: buttons = [],
          channel: {
              enable: channelEnable = false,
              id: channelIds = []
          } = {},
          keywords = [],
          keywordResponses = {},
          loader: {
              loadingMessage = 'loading...',
              loadingTimer = 3000,
              enable: loaderEnable = false
          } = {},
          permissions: {
              enable: permissionEnable = false,
              role = [],
              permission = [],
              blockedUsers = []
          } = {}
      } = {}
  } = aiOptions;


  if (onMention && usermsg) {
    const botMention = `<@${message.client.user.id}>`;

    if (!usermsg.startsWith(botMention)) return;

    usermsg = usermsg.replace(botMention, '').trim();
  }

  if (!message.guild) {
    return;
  }

    if (permissionEnable) {
      if (role.length > 0) { 
          const userRoles = message.member?.roles.cache.map((role: any) => role.id);
          const hasPermission = userRoles?.some((roleId: any) => role.includes(roleId));
          if (!hasPermission) return;
      } 

      if (permission.length > 0) {
        const hasPermission = permission.some(perm => message.member?.permissions.has(perm as PermissionResolvable));
        if (!hasPermission) return;
    }

      if (blockedUsers.length > 0) {
        const userId = message.author.id;
         if (blockedUsers.includes(userId)) return;
      }
    }

     if (channelEnable && !channelIds.includes(message.channel.id)) return;

     // @ts-ignore
     await message.channel?.sendTyping();

    if (message.attachments.size > 0) {
      message.attachments.forEach(async (attachment: any) => {
        try {
          const url = attachment.url;
          const contentType = attachment.contentType;
          const voiceSize = attachment.size;

          if (contentType.startsWith('audio/')) {
            if (voiceSize > (25 * 1024 * 1024)) return 'Voice/Audio file uploaded has is bigger than 25MB please decrease its size and resend it.'
          usermsg += await whisper(usermsg, url, lang)
          }
        } catch (e: any) {}
      });
    }

      const attachment = message.attachments?.first();
      const imgURL = attachment?.url || null;
      
      const validExtensions = /\.(png|jpg|jpeg|webp)$/i;
      
      if (readImages && attachment && validExtensions.test(attachment?.name) && imgURL && !['gemini-pro', 'gemini-flash'].includes(chatModel)) {
        usermsg = await groqAnalyzer({ imgURL, ApiKey: groqAPI, prompt: usermsg });
        usermsg += `\n-# I know you are text-based AI and can't view the images so here is the details regarding it:\n ${usermsg}`;
      }


   if (msgType === 'reply') {
     if (imgURL === null && usermsg === '') {
      return await message.reply({
        content: "You need to provide a message or an attachment at least.",
        allowedMentions: { repliedUser: false },
      });
    }
  } else if (msgType === 'send') {
    if (imgURL === null && usermsg === '') {
      // @ts-ignore
      return await message.channel.send({
        content: "You need to provide a message or an attachment at least.",
        allowedMentions: { repliedUser: false },
      });
    }
  }

  if (aiOptions.chat && readFiles && !['gemini-pro', 'gemini-flash'].includes(chatModel)) {
    if (message.attachments?.size > 0) {
            if (attachment?.name.endsWith('.pdf')) {
                const pdfContent = await readFile(attachment.url, 'pdf');
                usermsg += `\n\n- This is the pdf file content:\n\n ${pdfContent}`;
            } else {
                const txtContent = await readFile(attachment?.url as string, 'txt');
                usermsg += `\n\n- This is the .txt file content:\n\n ${txtContent}`;
            }
         }
      }

     if (aiOptions.others?.loader !== null && loaderEnable === true) {
      if (msgType === 'reply') {
        await message.reply({
          content: loadingMessage,
          allowedMentions: { repliedUser: false },
        }).then((replyMessage: any) => {
          setTimeout(() => {
            replyMessage.delete().catch(console.error);
          }, loadingTimer || 3000);
        });
       } else if (msgType === 'send') {
        // @ts-ignore
        await message.channel.send({
          content: loadingMessage
        }).then((replyMessage: any) => {
          setTimeout(() => {
            replyMessage.delete().catch(console.error);
          }, loadingTimer || 3000);
        });
       }
      }

      // @ts-ignore
      await message.channel?.sendTyping();

      let replied: string = "";


      if (message.reference?.messageId) {
        const channel = message?.guild?.channels?.cache?.get(message.channel.id);
        const messageId = message?.reference?.messageId;
        // @ts-ignore
        const fetchedMessage = await channel?.messages?.fetch(messageId);

        if (fetchedMessage.content) {
          replied += fetchedMessage.content;
        }  
  
        if (fetchedMessage.attachments && validExtensions.test(fetchedMessage.attachments.name)) {
          replied += await groqAnalyzer({ imgURL: fetchedMessage.attachments?.first().url, ApiKey: groqAPI, prompt: usermsg });
          usermsg += `\n-# I know you are text-based AI and can't view the images so here is the details regarding it:\n ${replied}`;
          usermsg = `${usermsg}\n\n-# Note: Read previous message: \n${replied}.\n\n`;
        }
      }

      let response: Response = '';

      for (const keyword of keywords) {
        if (usermsg.toLowerCase().includes(keyword.toLowerCase())) {
          response = keywordResponses[keyword] || "";
          return await message.reply({
            content: response,
            allowedMentions: { repliedUser: false },
          });
        }
      }

      const drawValid: any = aiOptions.imagine && imagineEnable && toDraw(usermsg, drawTrigger);
      const number = numOfImages; 
      const model = imageModel;

      if (drawValid) {   
        const matchingTrigger = drawTrigger.find(trigger => usermsg.startsWith(trigger));

        if (matchingTrigger) {
          usermsg = usermsg.substring(matchingTrigger.length).trim();
        }

        if (enhancerOn) {
          usermsg = `Rewrite this text below in more descriptive way make it clear to be visualized correctly and enhance it and use stronger words please and please return the response with nothing else in just the enhanced prompt nothing more nothing less\n\n\n ${usermsg}`
          const enhancemsg  = await hercai.question({ model: "v3-32k", content: usermsg});
          usermsg = enhancemsg.reply
        }

        return await aiImagine(
          message,
          number,
          usermsg,
          hercai,
          model,
          nsfwEnabled,
          nsfwKeyWords,
          deepCheck,
          aiOptions.imagine?.enhancer,
          buttons,
          RespondMessage,
          { rsnAPI: rsnAPIkey, groqAPI, prodiaAPI, freesedGPTApi: freesedGPTApi as string, electronHubKey: electronHubKey as string }
        );

    } else if (aiOptions.voice?.textVoice?.enable) {
        
      if (aiOptions.voice.textVoice && textVoiceEnable) {
        return await aiVoice(
          message,
          numOfImages,
          usermsg,
          hercai,
          drawValid,
          model,
          chatModel,
          textVoiceModel,
          textVoiceCode,
          textVoiceApiKey, 
          textVoiceType,
          nsfwEnabled,
          nsfwKeyWords,
          deepCheck,
          aiOptions.imagine?.enhancer,
          buttons,
          RespondMessage,
          { rsnAPI: rsnAPIkey, groqAPI, prodiaAPI,  freesedGPTApi: freesedGPTApi as string, electronHubKey: electronHubKey as string }
        );
      }
 
    if (msgType === 'reply') {
      if (usermsg.length >= 2000) {
        return await message.reply({
          content: 'Your message is too long for me to process. Please try sending a shorter message.',
          allowedMentions: { repliedUser: false },
      });
      } 
    } else if (msgType === 'send' ) {
      if (usermsg.length >= 2000) {
        // @ts-ignore
        return await message.channel.send({
          content: 'Your message is too long for me to process. Please try sending a shorter message.'
      });
      } 
    }
      } else if (chatEnable) {
        try { 
        if (modelsValidate.validotherChatModels.includes(chatModel)) {
          response = await otherChatModels({ modelName: chatModel as any, prompt: usermsg });
        } else if (modelsValidate.validgroqChatModels.includes(chatModel)) { 
          response = await chatGroq({ API_KEY: groq_API as string | undefined, prompt: usermsg, apiName: chatModel, instruction})
        } else if (chatModel === 'gemini-flash' || chatModel === 'gemini-pro') {
            const geminiFunction = chatModel === 'gemini-flash' ? geminiFlash : geminiPro;
        
            response = await geminiFunction(
              {
                  userId: message.author.id,
                  serverName: message.guild?.name as string,
                  serverId: message.guild?.id as string,
                  // @ts-ignore
                  channelName: message.channel.name,
                  attachment: attachment,
                  db: memoryOn
              },
              {
                  userMsg: usermsg,
                  API_KEY: geminiAPI,
                  AiPersonality: personality
              }
            );
        } else if (modelsValidate.validHercChatModels.includes(chatModel)) {
          response = await chatHercai(usermsg, chatModel as any, instruction, { enable: memoryOn, id: memoryId });
        } else if (modelsValidate.validElectronModels.includes(chatModel)) { 
          response = await electronChat({ ApiKey: electronHub_Key as string, prompt: usermsg, instruction, modelName: chatModel });
        } else {
          throw new Error('Invalid chat model. Check documentation for valid chat models.')
        }
        } catch (error: any) {
          if (msgType === 'reply') {
            if (error.response && error.response.status === 429) {
                console.error("Too many requests. Please try again later.");
                RespondMessage = await message.reply({ content: `Please wait i am in a cool down for a minute`, components: buttons });
                return;
            } else if (error.response && error.response.status === 500) {
                console.error("Internal server error. Please try again later.");
                RespondMessage = await message.reply({ content: `Please wait i am in a cool down for a minute`, components: buttons });
                return;
            } else {
                console.error("The Api is on a cool down for 10 seconds", error.message);
                RespondMessage = await message.reply({ content: `Please wait i am in a cool down for a minute`, components: buttons });
                return;
            }
          } else if (msgType === 'send') {
            if (error.response && error.response.status === 429) {
              console.error("Too many requests. Please try again later.");
              // @ts-ignore
              RespondMessage = await message.channel.send({ content: `Please wait i am in a cool down for a minute`, components: buttons });
              return;
          } else if (error.response && error.response.status === 500) {
              console.error("Internal server error. Please try again later.");
              // @ts-ignore
              RespondMessage = await message.channel.send({ content: `Please wait i am in a cool down for a minute`, components: buttons });
              return;
          } else {
            // @ts-ignore
              await message.channel.send({ content: `Please wait i am in a cool down for a minute`, components: buttons });
              console.error("The Api is on a cool down for 10 seconds", error.message);
          }
          }
        }
        response = `${msgContent}${response}`
        if (!returnChat) {
          return {
            response
          }
        }
      if (msgType === 'reply') {
        if (typeWritingEnable) {
          if (response.length <= 2000) {
              await typeWriter(message.channel, response, speed, delay, buttons);
          } else {
              let parts: string[] = [];
              while (typeof response === 'string' && response.length > 0) {
                  const substring = response.substring(0, 1999);
                  parts.push(substring);
                  if (response.length > 1999) {
                      response = response.substring(1999); 
                  } else {
                      break;
                  }
              }
              for (const part of parts) {
                RespondMessage =  await typeWriter(message.channel, part, speed, delay, buttons);
              }
          }

      } else {
          if (response.length <= 2000) {
            RespondMessage = await message.reply({
                  content: response,
                  components: buttons,
                  allowedMentions: { repliedUser: false },
              });
          } else {
            let parts: string[] = [];
            while (typeof response === 'string' && response.length > 0) {
                const substring = response.substring(0, 1999);
                parts.push(substring);
                if (response.length > 1999) {
                    response = response.substring(1999); 
                } else {
                    break;
                }
            }
              for (const part of parts) {
                RespondMessage =  await message.reply({
                      content: part,
                      components: buttons,
                      allowedMentions: { repliedUser: false },
                  });
              }
          }
        }
      } else if (msgType === 'send') {
        if (typeWritingEnable) {
            if (response.length <= 2000) {
              RespondMessage = await typeWriter(message.channel, response, speed, delay, buttons);
            } else {
                let parts: string[] = [];
                while (typeof response === 'string' && response.length > 0) {
                    const substring = response.substring(0, 1999);
                    parts.push(substring);
                    if (response.length > 1999) {
                        response = response.substring(1999);
                    } else {
                        break;
                    }
                }
                for (const part of parts) {
                  RespondMessage =  await typeWriter(message.channel, part, speed, delay, buttons);
                }
            }
        } else {
            if (response.length <= 2000) {
              // @ts-ignore
              RespondMessage = await message.channel.send({
                    content: response,
                    components: buttons
                });
            } else {
                let parts: string[] = [];
                while (typeof response === 'string' && response.length > 0) {
                    const substring = response.substring(0, 1999);
                    parts.push(substring);
                    if (response.length > 1999) {
                        response = response.substring(1999);
                    } else {
                        break;
                    }
                }
                for (const part of parts) {
                  // @ts-ignore
                  RespondMessage = await message.channel.send({
                        content: part,
                        components: buttons
                    });
                }
            }
        }
    }
  } else {
    throw new Error('You need to at least enable a single functionality: Chat | Image | Voice Speech.')
  }
  return await RespondMessage;
};